delete from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

delete from WFL_STL_PAY_ORDERS 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
and TRADE_ID in 
(select TOTLE_TRADE_ID from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

)

delete from WFL_PA_TRD_FIN_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
and TOTLE_TRADE_ID in 
(select TOTLE_TRADE_ID from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

)

delete from WFL_TRD_PRODUCT_DEAL 
where (WORKFLOW_ID is null or WORKFLOW_ID = '')
    and BUSI_TYPE = #{busiType}

    and FINPROD_TYPE2 = #{finProdType2}

mapper.select:
 T1
WHERE
T1.PORTFOLIO_ID = #{ portfolioId}
AND T1.SEC_ACCT_ID = #{ secAcctId}
AND T1.FINPROD_ID = #{ finprodId}
AND T1.BRANCH = #{ branch}
AND T1.HODING_TYPE = #{ hodingType}
AND T1.CDATE <= #{cdate}
and not exists (select 1 from PTL_SEC_POSITION T2 where  T2.PORTFOLIO_ID = T1.PORTFOLIO_ID
    AND T2.SEC_ACCT_ID   = T1.SEC_ACCT_ID
    AND T2.FINPROD_ID    = T1.FINPROD_ID
    AND T2.BRANCH        = T1.BRANCH
    AND T2.HODING_TYPE   = T1.HODING_TYPE
    AND T2.CDATE         <= #{cdate}
    AND T2.CDATE > T1.CDATE
)

mapper.delete:
delete from PA_TRD_FIN_PRODUCT_DEAL_TOTAL tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
  and BUSI_TYPE = #{busiType}
  and update_user = #{updateUser}

    and FINPROD_TYPE2 = #{finProdType2}

)
and  not exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO  WHERE SETTLE_STATUS = '02' and TRADE_ID = tfpft.TOTLE_TRADE_ID)

delete from TRD_FIN_PRODUCT_DEAL_TOTAL tfpft
where tfpft.trade_date =#{batchDate}
  and tfpft.BUSI_TYPE = #{busiType}
  and tfpft.update_user = #{updateUser}

    and tfpft.FINPROD_TYPE2 = #{finProdType2}

and  not exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO  WHERE SETTLE_STATUS = '02' and TRADE_ID = tfpft.TOTLE_TRADE_ID)

delete from trd_product_deal tfpft
where tfpft.trade_date =#{batchDate}
and tfpft.update_user = #{updateUser}

    and tfpft.FINPROD_TYPE2 = #{finProdType2}

and  not exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO  WHERE SETTLE_STATUS = '02' and TRADE_ID = tfpft.TOTLE_TRADE_ID)

delete from trd_product_deal_add tfpft
where tfpft.trade_id in (
    select trade_id from trd_product_deal
    where trade_date =#{batchDate}
    and update_user = #{updateUser}

        and FINPROD_TYPE2 = #{finProdType2}

)
and not exists (select 1 from trd_product_deal TT where TT.TRADE_ID = tfpft.TRADE_ID AND  exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO where SETTLE_STATUS = '02' and TRADE_ID = TT.TOTLE_TRADE_ID))

delete from PA_TRD_PROD_TEMP_DEAL_TOTAL tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_PRODUCT_TEMP_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and update_user = #{updateUser}

    and TRADE_MARKET = #{tradeMarket}


    and FINPROD_TYPE2 = #{finProdType2}

)
and  not exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO  WHERE SETTLE_STATUS = '02' and TRADE_ID = tfpft.TOTLE_TRADE_ID)

delete from TRD_PRODUCT_TEMP_DEAL_TOTAL tfpft
where tfpft.trade_date =#{batchDate}
and tfpft.BUSI_TYPE = #{busiType}
and tfpft.update_user = #{updateUser}

    and tfpft.TRADE_MARKET = #{tradeMarket}


    and tfpft.FINPROD_TYPE2 = #{finProdType2}

and  not exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO  WHERE SETTLE_STATUS = '02' and TRADE_ID = tfpft.TOTLE_TRADE_ID)

delete from TRD_PRODUCT_TEMP_DEAL tfpft
where tfpft.trade_date =#{batchDate}
and tfpft.update_user = #{updateUser}

    and tfpft.TRADE_MARKET = #{tradeMarket}


    and tfpft.FINPROD_TYPE2 = #{finProdType2}

and  not exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO  WHERE SETTLE_STATUS = '02' and TRADE_ID = tfpft.TOTLE_TRADE_ID)

delete from TRD_PRODUCT_TEMP_DEAL_ADD tfpft
where tfpft.trade_id in (
select trade_id from TRD_PRODUCT_TEMP_DEAL
where trade_date =#{batchDate}
and update_user = #{updateUser}

    and TRADE_MARKET = #{tradeMarket}


    and FINPROD_TYPE2 = #{finProdType2}

)
and not exists (select 1 from trd_product_deal TT where TT.TRADE_ID = tfpft.TRADE_ID AND  exists (select 1 from TRD_BANK_MANUAL_SETTLE_INFO where SETTLE_STATUS = '02' and TRADE_ID = TT.TOTLE_TRADE_ID))

delete from STL_PAY_TEMP_ORDERS tfpft
where tfpft.settle_date =#{batchDate}
and tfpft.update_user = #{updateUser}
and tfpft.ORDER_ID not in (select stl.ORDER_ID from STL_PAY_ORDERS stl )
